function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
const items = $input.all();
return items.filter(item => {
  const j = item.json || {};
  // Grundvoraussetzung: echter Facebook-Content vorhanden (analog Mastodon-Filter,
  // dort instagramCaption/facebookPost als Fallback-Paar - hier facebookPost zuerst,
  // da das der spezifisch fuer diesen Kanal generierte Text ist).
  if (!safeStr(j.facebookPost)) return false;
  if (safeBool(j.facebookPosted)) return false;
  if (!safeStr(j.vorgangKey)) return false;
  // Gleiches Wettlauf-Muster wie P9 vs. P6: bei sharepicNeedStage=topic_ok wird auf das
  // fertige Bild gewartet (P6), ausser das Bildkonzept ist endgueltig gescheitert
  // (imageStage=topic_error_final) - dann text-only posten statt ewig zu warten.
  // FIX 2026-08-26 (Live-Test): wordpressGoslarImageUrl wird in der gesamten Tabelle nie
  // befuellt (0 von 240 Zeilen) - imageFinalPath (NextCloud-Pfad, von P6 befuellt) ist das
  // tatsaechlich nutzbare Feld, analog zu P9 Mastodon.
  if (safeStr(j.sharepicNeedStage) === 'topic_ok') {
    const hasImage = !!safeStr(j.imageFinalPath);
    const imageGivenUp = safeStr(j.imageStage) === 'topic_error_final';
    const waitingForImage = !hasImage && !imageGivenUp;
    if (waitingForImage) return false;
  }
  // Facebook-Post verlinkt auf den diePARTEI-Wordpress-Artikel, muss also immer nach P8
  // kommen (identisches Muster zu P9).
  if (!safeBool(j.wordpressGoslarPosted)) return false;
  if (!safeStr(j.wordpressGoslarPostLink)) return false;
  return true;
});

// Nutzerentscheidung 2026-08-30: aufsteigende Brisanz zum 13.09. (Kommunalwahl) -
// niedrige/mittlere Brisanz zuerst posten, die brisantesten Themen fuer die letzten
// Tage vor der Wahl aufsparen (Recency-Effekt: was unmittelbar vor dem Waehlen zu
// sehen ist, wirkt ueberproportional staerker nach). Kapazitaet (15 Laeufe/Tag, siehe
// Schedule Trigger) ist bewusst so bemessen, dass der Rueckstand (170, Stand 30.08.)
// bis zum 13.09. komplett abgearbeitet wird - die am hoechsten bewerteten Vorgaenge
// landen dadurch automatisch in den letzten Tagen vor der Wahl, ohne ein festes Datum
// im Code zu verdrahten. combinedScore kombiniert kommunikationspotenzial (0-8, von P3)
// mit sprengstoff (KEINER/GERING/MITTEL/HOCH, x3 gewichtet, da das die eigentliche
// "Brisanz"-Dimension ist). Alter bleibt nur noch Tie-Breaker innerhalb gleicher Scores -
// kein Anti-Verhungerungs-Mechanismus noetig, da die Kapazitaet den ganzen Rueckstand deckt.
// ACHTUNG: nach dem 13.09. neu bewerten - reine Score-Sortierung ohne Alters-Schutz kann
// im Dauerbetrieb niedrig bewertete Vorgaenge unbegrenzt liegen lassen.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeNum(v) { const n = Number(v); return isNaN(n) ? 0 : n; }
const SPRENGSTOFF_WEIGHT = { KEINER: 0, GERING: 1, MITTEL: 2, HOCH: 3 };
function combinedScore(j) {
  const kompot = safeNum(j.kommunikationspotenzial);
  const sprengstoff = SPRENGSTOFF_WEIGHT[safeStr(j.sprengstoff).toUpperCase()] || 0;
  return kompot + sprengstoff * 3;
}
return [...items].sort((a, b) => {
  const sa = combinedScore(a.json), sb = combinedScore(b.json);
  if (sa !== sb) return sa - sb;
  const ta = Date.parse(a.json.lastAnalysisAt || '') || 0;
  const tb = Date.parse(b.json.lastAnalysisAt || '') || 0;
  return ta - tb;
}).slice(0, 1);

const now = Date.now();
const owner = `ALLRIS_P11_Facebook_Publish:${$execution.id}`;
return items
  .filter(item => {
    const j = item.json || {};
    const oldOwner = String(j.claim_owner || '').trim();
    const expires = Date.parse(String(j.claim_expires_at || ''));
    return !oldOwner || !Number.isFinite(expires) || expires <= now;
  })
  .map(item => ({ json: {
    ...item.json,
    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: item.json.claim_owner ?? null,
    expectedClaimExpiresAt: item.json.claim_expires_at ?? null
  } }));

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseArr(v) {
  try { const a = JSON.parse(v); return Array.isArray(a) ? a : []; } catch (e) { return []; }
}
// Gleicher defensiver Fix wie in P9 (Baue Toot-Text): P4-Prompt liess GPT-5-mini teils
// woertlich "Hook:" als Label mit ausgeben, bereits generierte, noch nicht geposteten
// Captions in der Data Table koennen das noch enthalten.
function stripHookLabel(s) { return safeStr(s).replace(/^\s*Hook\s*:\s*/i, ''); }
function sanitizeTag(t) { return safeStr(t).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, ''); }
// Gleiche feste Pflicht-Hashtags wie P9 (Nutzervorgabe), am Ende der Hashtag-Zeile.
const FIXED_HASHTAGS = ['meingoslar', 'goslar', 'unserklüngelkannmehr', 'prioritätenproblem'];

const j = $json;
// facebookPost zuerst (kanal-spezifisch generiert), instagramCaption als Fallback -
// umgekehrte Prioritaet zu P9 (dort instagramCaption zuerst), da facebookPost hier der
// eigentlich vorgesehene Text ist.
const caption = stripHookLabel(safeStr(j.facebookPost) || safeStr(j.instagramCaption));
const postLink = safeStr(j.wordpressGoslarPostLink);

const rawTags = parseArr(j.facebookHashtags).length ? parseArr(j.facebookHashtags) : parseArr(j.instagramHashtags);
const sanitized = rawTags.map(sanitizeTag).filter(Boolean);
const seen = new Set();
const tags = [];
for (const t of [...sanitized, ...FIXED_HASHTAGS]) {
  const key = t.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  tags.push('#' + t);
}
const hashtagLine = tags.join(' ');

// Facebook-Posts haben (anders als Mastodons 800-Zeichen-Limit) praktisch kein relevantes
// Limit (63.206 Zeichen) - deshalb keine Kuerzungslogik noetig, anders als bei P9.
let postText = caption;
if (postLink) postText += '\n\n' + postLink;
if (hashtagLine) postText += '\n\n' + hashtagLine;

// Oeffentliche Bild-URL direkt uebergeben (wie P10 Instagram) statt ueber Nextcloud
// herunterzuladen und als multipart-Datei hochzuladen (wie P9 Mastodon) - Facebooks
// /photos-Endpunkt akzeptiert eine URL direkt.
const hasImage = !!safeStr(j.imageFinalPath);

return { json: { ...j, facebookPostText: postText, hasImage } };

const original = $('Baue Facebook-Post').itemMatching($itemIndex).json;
const result = $json || {};
// Gleicher defensiver Fix wie P9 (Stelle Kontext nach Post-Erstellung wieder her): n8n haengt
// bei onError=continueRegularOutput den Fehler oft als Objekt statt String ein.
function extractErrorText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return String(v.message || v.description || v.error || JSON.stringify(v));
  return String(v);
}
// /photos liefert {id, post_id}, /feed liefert nur {id} (das ist dort schon die volle
// Post-ID im Format {page-id}_{post-id}) - post_id hat bei /photos Vorrang, sonst id.
const postId = result.post_id || result.id || null;
const facebookPostLink = postId ? ('https://www.facebook.com/' + postId) : '';
return { json: {
  ...original,
  facebookPostId: postId,
  facebookPostLink,
  facebookError: postId ? '' : (extractErrorText(result.error) || 'Unbekannter Fehler beim Facebook-Post')
} };

// Gleicher Fix wie in P9 uebernommen: ALLRIS_Claim_Lease matcht Freigaben per id UND
// claim_owner - ohne id laeuft die Freigabe stillschweigend ins Leere.
const vorgangKey = String($json.vorgangKey || '').trim();
const id = $json.id;
if (!vorgangKey || !id) return [];
return [{ json: { id, vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_P11_Facebook_Publish:${$execution.id}` } }];

